def f(p):
    s = p['S0']
    D = 0
    for d in range(1, p['T'] + 1):
        if d % p['a'] == 0:
            s += p['b']
        if s > p['cap']:
            s = p['cap']
        dem = p['c'] + d % p['e']
        if s >= dem:
            s -= dem
        else:
            D += dem - s
            s = 0
        if d % p['f'] == 0:
            s -= s // 10
    return D

def dig(v, d):
    while v > 0:
        if v % 10 == d:
            return True
        v //= 10
    return False
def f(p):
    v = 0
    bells = 0
    for _ in range(p['T']):
        q0 = v // p['B']
        v += p['k']
        while dig(v, p['d']):
            v += 1
        if v // p['B'] > q0:
            bells += 1
    return bells

def f(p):
    x = 0
    n = 0
    while True:
        x += p['up']
        n += 1
        if x >= p['goal']:
            return n
        x -= p['down']
